//! Runtime COMBINE execution boundary.
use crate::combine::{bond_strength,eligible_candidates,required_investment,ExperimentalInteraction,FormationEvaluation};
use crate::contact::ConnectionCompatibilityCache;
use crate::resources::{BaseResource,ConnectionSites};
use crate::state::{Environment,Organism};
use crate::structure::{BondEndpoint,ConnectionEndpoint,Placement,StructuralUnit};
const EPSILON:f64=1e-12;const COMBINE_CONTACT_TOLERANCE:f64=1.0;
#[derive(Clone,Copy,Debug,PartialEq)]pub(crate)struct CombineAttempt{pub unit_a:usize,pub unit_b:usize,pub endpoint_a:ConnectionEndpoint,pub endpoint_b:ConnectionEndpoint,pub work_cost:f64,pub energy_invested:f64,pub interaction_direction:f64,pub interaction_magnitude:f64,pub interaction_energy:f64,pub formation_threshold:f64,pub net_energy_change:f64,pub bond_strength:f64,pub bond_energy:f64}
fn water_field_amount(environment:&Environment,organism:&Organism)->f64{organism.occupied_cells.first().and_then(|p|environment.field.index_for_position(p.x,p.y)).map(|i|environment.field.cells[i].materials.iter().map(|m|{if let Some(s)=m.structure(){s.constituents.iter().filter(|c|c.resource=="Water").count()as f64}else{m.composition().iter().filter(|c|c.resource=="Water").map(|c|c.amount).sum()}}).sum()).unwrap_or(0.0)}
fn energy_requirement(investment:f64,work:f64,interaction:f64)->Option<f64>{if !investment.is_finite()||investment<0.0||!work.is_finite()||work<0.0||!interaction.is_finite(){return None}Some((investment+work-interaction).max(0.0))}
fn settle_energy(energy:&mut f64,investment:f64,work:f64,interaction:f64)->Option<f64>{let required=energy_requirement(investment,work,interaction)?;if *energy+EPSILON<required{return None}let net=interaction-investment-work;let next=*energy+net;if !net.is_finite()||!next.is_finite()||next< -EPSILON{return None}*energy=next.max(0.0);Some(net)}
fn evaluate_candidate(s:&crate::structure::OrganismStructure,ua:usize,ub:usize,candidate:crate::contact::ConnectionPairCandidate,catalog:&[BaseResource],water:f64)->Option<(FormationEvaluation,ExperimentalInteraction,f64,f64,f64)>{if candidate.distance>COMBINE_CONTACT_TOLERANCE{return None}let a=s.units.get(ua)?.properties(catalog)?;let b=s.units.get(ub)?.properties(catalog)?;let e=crate::combine::evaluate_formation(candidate,a.cohesion,b.cohesion);let(i,w,investment)=required_investment(a,b,e,water).ok()?;let required=energy_requirement(investment,w,i.signed_value)?;Some((e,i,w,investment,required))}
fn form_bond(s:&mut crate::structure::OrganismStructure,ua:usize,ub:usize,ea:ConnectionEndpoint,eb:ConnectionEndpoint,investment:f64,water:f64,catalog:&[BaseResource],cache:&mut ConnectionCompatibilityCache,energy:&mut f64)->Option<CombineAttempt>{if ua>=s.units.len()||ub>=s.units.len()||ua==ub{return None}let candidate=crate::contact::connection_pair_candidates_cached(s,ua,ub,catalog,cache).into_iter().find(|c|c.endpoint_a==ea&&c.endpoint_b==eb&&c.distance<=COMBINE_CONTACT_TOLERANCE)?;let(a,b)=(s.units[ua].properties(catalog)?,s.units[ub].properties(catalog)?);let e=crate::combine::evaluate_formation(candidate,a.cohesion,b.cohesion);if !crate::combine::formation_succeeds(e,investment){return None}let(i,w,threshold)=required_investment(a,b,e,water).ok()?;if(threshold-investment).abs()>EPSILON{return None}let strength=bond_strength(a,b);if !strength.is_finite(){return None}let mut trial=s.clone();let bond=crate::structure::Bond{endpoint_a:BondEndpoint{unit_index:ua,location:ea},endpoint_b:BondEndpoint{unit_index:ub,location:eb},strength,bond_energy:investment};crate::contact::try_add_bond(&mut trial,bond,catalog).ok()?;let mut trial_energy=*energy;let net=settle_energy(&mut trial_energy,investment,w,i.signed_value)?;*s=trial;*energy=trial_energy;Some(CombineAttempt{unit_a:ua,unit_b:ub,endpoint_a:ea,endpoint_b:eb,work_cost:w,energy_invested:investment,interaction_direction:i.direction,interaction_magnitude:i.magnitude,interaction_energy:i.signed_value,formation_threshold:threshold,net_energy_change:net,bond_strength:strength,bond_energy:investment})}
pub(crate)fn instantiate_one_unit(organism:&mut Organism,catalog:&[BaseResource])->Option<usize>{let material=organism.stored_material.peek_one_unstructured()?;let c=material.composition();if c.len()!=1||(c[0].amount-1.0).abs()>EPSILON||catalog.iter().all(|b|b.name!=c[0].resource){return None}let name=c[0].resource.clone();let material=organism.stored_material.take_one_unstructured_named(&name)?;let(x,y)=organism.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));Some(organism.structure.add_unit(StructuralUnit::from_material(material,Placement{x,y,rotation_radians:0.0})?))}
pub(crate)fn try_combine_stored_unit(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{let raw=organism.stored_material.peek_one_unstructured()?;let c=raw.composition();if c.len()!=1||(c[0].amount-1.0).abs()>EPSILON{return None}let name=c[0].resource.clone();if environment.catalog.iter().all(|b|b.name!=name){return None}let water=water_field_amount(environment,organism);let mut best=None;for ua in 0..organism.structure.units.len(){for candidate in crate::contact::connection_pair_candidates_cached(&organism.structure,ua,ua, &environment.catalog,cache){let _=candidate;}}for ub in 0..organism.structure.units.len(){let _=ub;}
// The actual placement search remains physical-candidate driven. This boundary
// intentionally handles only one new unstructured constituent; structured
// stored assemblies require composite external-interface realization.
let resource=environment.catalog.iter().find(|b|b.name==name)?;let Some(ConnectionSites::Corners(new_sites))=resource.shape.connection_sites()else{return None};for ua in 0..organism.structure.units.len(){let Some(ConnectionSites::Corners(existing))=organism.structure.units[ua].connection_sites(&environment.catalog)else{continue};for(ep_a,_)in existing.iter().enumerate(){for(ep_b,_)in new_sites.iter().enumerate(){let placement=organism.structure.units[ua].placement;let mut trial=organism.structure.clone();let ub=trial.add_unit(StructuralUnit::new(name.clone(),placement));let candidate=crate::contact::connection_pair_candidates_cached(&trial,ua,ub,&environment.catalog,cache).into_iter().find(|x|x.endpoint_a==ConnectionEndpoint::Corner{point_index:ep_a}&&x.endpoint_b==ConnectionEndpoint::Corner{point_index:ep_b})?;let Some((e,_,_,investment,required))=evaluate_candidate(&trial,ua,ub,candidate,&environment.catalog,water)else{continue};if organism.usable_energy+EPSILON<required{continue}best=Some((ua,ub,e,investment));}}}let(ua,ub,e,investment)=best?;let mut energy=organism.usable_energy;let attempt=form_bond(&mut organism.structure,ua,ub,e.candidate.endpoint_a,e.candidate.endpoint_b,investment,water,&environment.catalog,cache,&mut energy)?;organism.stored_material.take_one_unstructured_named(&name)?;organism.usable_energy=energy;organism.add_transaction_stress(attempt.work_cost);Some(attempt)}
pub(crate)fn try_combine(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{if !organism.structure.units.is_empty(){if let Some(a)=try_combine_stored_unit(organism,environment,cache){return Some(a)}}if organism.structure.units.len()<2{return None}let water=water_field_amount(environment,organism);let mut best=None;for ua in 0..organism.structure.units.len(){for ub in ua+1..organism.structure.units.len(){for c in eligible_candidates(&organism.structure,ua,ub,&environment.catalog,cache){let Some((e,_,_,investment,required))=evaluate_candidate(&organism.structure,ua,ub,c,&environment.catalog,water)else{continue};if organism.usable_energy+EPSILON<required{continue}if best.as_ref().map(|x:(usize,usize,FormationEvaluation,f64,f64)|c.distance<x.4).unwrap_or(true){best=Some((ua,ub,e,investment,required));}}}}let(ua,ub,e,investment,_)=best?;let mut energy=organism.usable_energy;let attempt=form_bond(&mut organism.structure,ua,ub,e.candidate.endpoint_a,e.candidate.endpoint_b,investment,water,&environment.catalog,cache,&mut energy)?;organism.usable_energy=energy;organism.add_transaction_stress(attempt.work_cost);Some(attempt)}
